function letterBlock(l,t){const L=LBYID(l.template_code)||{name:l.template_code};return'<div class="card" style="background:#f9fbfe" data-testid="letter-block-'+l.id+'"><b>'+h(L.name)+'</b> '+pill(LST[l.status],stc(l.status))+(l.ref?' <b>'+h(l.ref)+'</b>':'')+'<div class="small mute">v'+l.current_version+' · prepared by '+h(l.preparer_email)+' ('+h(l.preparer_role)+')'+(l.reviewer_email?' · vetted by '+h(l.reviewer_email)+" "+dtt(l.reviewed_at):'')+(l.released_by?' · released by '+h(l.released_by)+" "+dtt(l.released_at):'')+(l.ack_type?' · '+h(l.ack_type)+" "+dt(l.ack_date):'')+'</div>'+(l.events.filter(e=>e.comment).map(e=>'<div class="small">'+dtt(e.at)+' '+h(e.by_email)+' — '+h(e.action)+': '+h(e.comment)+'</div>').join(""))+'<div class="bar" style="margin-top:6px"><button class="btn sm" data-lopen="'+l.id+'" data-testid="letter-open-'+l.id+'">Open letter</button></div></div>'}
function valsFromTxn(L,t){const d=t.data,v={};const inv={};Object.keys(MAPV).forEach(k=>inv[k]=MAPV[k]);
 L.f.forEach(f=>{let x=d[f.k]!=null?d[f.k]:inv[f.k]?d[inv[f.k]]:"";if(!x&&f.k==="pos")x=d.new_designation;if(!x&&f.k==="basic")x=d.new_basic;if(!x&&f.k==="ref_date")x=t.created_at.slice(0,10);if(!x&&f.k==="ref_doc")x=(mvBy(t.movement_code).name||"request")+" ("+t.ref+")";v[f.k]=x||f.d||""});
 CHG.forEach(([k])=>{if(v["c_"+k]==null&&d[inv["c_"+k]])v["c_"+k]=d[inv["c_"+k]];if(v["n_"+k]==null&&d[inv["n_"+k]])v["n_"+k]=d[inv["n_"+k]]});return v}
function editData(t,done){const ov=modal('<h2>Correct confirmed data</h2><p class="small mute">Allowed only before approval. Old and new values are kept in the audit trail.</p><div class="row2">'+FIELDS.map(f=>'<div><label>'+h(f.l)+'</label><input data-ef="'+f.k+'" value="'+h(t.data[f.k]||"")+'"></div>').join("")+'</div><label>Reason for correction</label><input id="ern"><div class="bar" style="margin-top:8px"><button class="btn" id="esv" data-testid="txn-edit-save">Save</button></div>',900);
 ov.querySelector("#esv").onclick=async()=>{const d={};ov.querySelectorAll("[data-ef]").forEach(i=>{if(i.value.trim())d[i.dataset.ef]=i.value.trim()});try{await api("txns/"+t.id,{method:"PUT",body:{ver:t.ver,data:d,note:ov.querySelector("#ern").value}});ov.remove();toast("Saved");done()}catch(e){err(e)}}}
