async function letterEditor(lid,txnId){const x=await api("txns/"+txnId);const l=x.letters.find(y=>y.id===lid),t=x.txn;const L=LBYID(l.template_code);if(!L){toast("Template not found");return}
 const cur=l.versions[l.versions.length-1];const vals=Object.assign({},cur.vals);L.f.forEach(f=>{if(vals[f.k]==null)vals[f.k]=f.d||""});
 const me=W.me.email,editable=!["released","acknowledged","superseded_withdrawn"].includes(l.status)&&isHR()&&!(l.status==="pending_vetting"&&me===l.preparer_email);
 const canV=l.preparer_email!==me&&canVetLocal(l);const released=["released","acknowledged"].includes(l.status);
 const xo=()=>({ref:l.ref||"",date:released?l.released_at.slice(0,10):today(),name:t.emp_name,id:t.emp_id||"",dept:t.data.cur_dept||"",sn:l.signatory_name,st:l.signatory_title,draft:!released});
 const fld=f=>'<div><label>'+h(f.l)+(f.opt?"":" *")+'</label><input data-lf2="'+f.k+'" value="'+h(vals[f.k]||"")+'"'+(f.t==="date"?' type="date"':"")+(editable?"":" disabled")+'></div>';
 const grid=L.f.some(f=>f.g==="chg")?'<label>Changes table (Current / New)</label><div class="chg"><b>Item</b><b>Current</b><b>New</b>'+CHG.map(([k,lb])=>'<span>'+h(lb)+'</span><input data-lf2="c_'+k+'" value="'+h(vals["c_"+k]||"")+'"'+(editable?"":" disabled")+'><input data-lf2="n_'+k+'" value="'+h(vals["n_"+k]||"")+'"'+(editable?"":" disabled")+'>').join("")+'</div>':"";
 const ov=modal('<h2 data-testid="letter-editor-title">'+h(L.name)+' — '+h(t.emp_name)+' <span class="small mute">'+h(t.ref)+'</span></h2><div class="bar">'+pill(LST[l.status],stc(l.status))+(l.ref?' <b data-testid="letter-ref">'+h(l.ref)+'</b>':'')+'<span class="small mute">Version '+l.current_version+(l.approved_version?" · approved version "+l.approved_version:"")+' · Signatory: '+h(l.signatory_name)+', '+h(l.signatory_title)+'</span></div>'+
  (l.status==="returned"?'<div class="callout o small"><b>Returned for amendment.</b> '+h((l.events.filter(e=>e.action==="returned_for_amendment").pop()||{}).comment||"")+'</div>':'')+
  (l.status==="approved_for_release"?'<div class="callout g small">Approved for release. Editing now cancels the approval and the letter must be vetted again.</div>':'')+
  '<div class="row2">'+L.f.filter(f=>f.g!=="chg").map(fld).join("")+'</div>'+grid+'<h3>Preview'+(released?"":" (DRAFT — no signature)")+'</h3><div class="lp" id="lpv2"></div>'+
  '<div style="margin-top:8px"><label>Comment</label><input id="lc2" data-testid="letter-comment"></div><div class="bar noprint" style="margin-top:10px">'+
  (editable?'<button class="btn sec" data-la="save" data-testid="letter-save-btn">Save new version</button>':'')+
  (["draft","returned","revised_draft"].includes(l.status)&&isHR()?'<button class="btn" data-la="submit" data-testid="letter-submit-btn">Submit for vetting</button>':'')+
  (l.status==="pending_vetting"&&canV?'<button class="btn" data-la="approve" data-testid="letter-approve-btn">Approve for release</button><button class="btn" data-la="release" data-testid="letter-release-btn">Approve and release</button><button class="btn red" data-la="return" data-testid="letter-return-btn">Return for amendment</button>':'')+
  (l.status==="approved_for_release"&&canV?'<button class="btn" data-la="release" data-testid="letter-release-btn">Release letter</button>':'')+
  (released?'<button class="btn" data-la="print" data-testid="letter-print-btn">Print / save PDF</button><button class="btn sec" data-la="docx" data-testid="letter-docx-btn">Download Word</button>':'<button class="btn grey" data-la="dprint" data-testid="letter-draft-print-btn">Print draft</button>')+
  (l.status==="released"&&isHR()?'<label class="btn sec">Record acknowledgement<input type="file" id="ackf" style="display:none" data-testid="letter-ack-input"></label><select id="ackt" data-testid="letter-ack-type"><option value="receipt">Receipt acknowledged</option><option value="acceptance">Express acceptance</option><option value="refused">Employee refused to sign</option></select>':'')+
  (released&&isHR()?'<button class="btn grey" data-la="supersede" data-testid="letter-supersede-btn">Correct / reissue</button>':'')+
  (!released&&l.status!=="superseded_withdrawn"&&isHR()?'<button class="btn grey" data-la="withdraw">Withdraw draft</button>':'')+
  '</div><h3>Version history</h3>'+table([["Version",v=>v.version],["Edited by",v=>h(v.edited_by)],["When",v=>dtt(v.edited_at)],["Note",v=>h(v.note||"")]],l.versions)+'<h3>Vetting history</h3>'+table([["When",e=>dtt(e.at)],["Who",e=>h(e.by_email)],["Action",e=>h(e.action)],["Version",e=>e.version],["Comment",e=>h(e.comment||"")]],l.events),940);
 ov.classList.add("v2le");const box=ov.querySelector("#lpv2");paintPreview(box,L,vals,xo());
 ov.addEventListener("input",e=>{const k=e.target.dataset.lf2;if(k){vals[k]=e.target.value;paintPreview(box,L,vals,xo())}});
 const after=()=>{ov.remove();showTxn(txnId)};
 const act=async(a,extra)=>{try{const r=await api("letters/"+lid+"/action",{body:Object.assign({action:a,ver:l.ver,comment:ov.querySelector("#lc2").value},extra||{})});toast(a==="release"?"Released "+(r.ref||""):"Done");if(a==="release"){after();letterEditor(lid,txnId).then(()=>fileFinal(lid,txnId))}else after()}catch(e){err(e)}};
 ov.addEventListener("click",async e=>{const b=e.target.closest("[data-la]");if(!b)return;const a=b.dataset.la;
  if(a==="save"){try{await api("letters/"+lid,{method:"PUT",body:{ver:l.ver,vals,note:ov.querySelector("#lc2").value}});toast("Saved new version");after()}catch(er){err(er)}}
  else if(a==="submit"){if(JSON.stringify(vals)!==JSON.stringify(Object.assign({},cur.vals,vals))||L.f.some(f=>!f.opt&&!vals[f.k])){const m=L.f.filter(f=>!f.opt&&!vals[f.k]);if(m.length){toast("Fill: "+m[0].l);return}}
   if(JSON.stringify(vals)!==JSON.stringify(cur.vals)){toast("Save the new version before submitting");return}act("submit")}
  else if(["approve","release","return","withdraw","supersede"].includes(a))act(a);
  else if(a==="dprint")printLetter(L,vals,xo());
  else if(a==="print"||a==="docx"){await withSig(lid,()=>{a==="print"?printLetter(L,vals,xo()):download(l.ref.replace(/\//g,"-")+" "+t.emp_name.replace(/[^A-Za-z0-9 ]/g,"")+".docx",docxBlob(L,vals,xo()),"application/vnd.openxmlformats-officedocument.wordprocessingml.document")})}});
 const ak=ov.querySelector("#ackf");if(ak)ak.onchange=async()=>{try{const d=await upload(ak.files[0],"acknowledgement",txnId);await api("letters/"+lid+"/action",{body:{action:"acknowledge",ver:l.ver,ack_type:ov.querySelector("#ackt").value,ack_doc_id:d.id,ack_date:today(),comment:ov.querySelector("#lc2").value}});toast("Acknowledgement recorded");after()}catch(er){err(er)}}}
async function withSig(lid,fn){LH_SIG="";let s=null;try{s=await api("letters/"+lid+"/signature")}catch(e){}
 if(!s||!s.available||!s.dataUrl){toast("The preserved signature must be configured in private storage before final letters can be generated.");return false}
 LH_SIG=s.dataUrl;
 try{await fn();return true}finally{LH_SIG=""}}

async function fileFinal(lid,txnId){try{const x=await api("txns/"+txnId);const l=x.letters.find(y=>y.id===lid),t=x.txn,L=LBYID(l.template_code),v=l.versions[l.versions.length-1].vals;
 const o={ref:l.ref,date:l.released_at.slice(0,10),name:t.emp_name,id:t.emp_id||"",dept:t.data.cur_dept||"",sn:l.signatory_name,st:l.signatory_title,draft:false};
 await withSig(lid,async()=>{const html=letterDoc(L,v,o,false);const blob=docxBlob(L,v,o);const buf=new Uint8Array(await blob.arrayBuffer());let s="";for(let i=0;i<buf.length;i+=0x8000)s+=String.fromCharCode(...buf.subarray(i,i+0x8000));
 await api("letters/"+lid+"/final",{body:{html,docx_b64:btoa(s)}})});}catch(e){console.warn("final file",e)}}

